-- Investigaciones posteriores al tutorial: afinidad separada de los matrimonios.
return {encounters={day3_nanahoshi_research="nano_fragment_review",day4_nanahoshi_research="nano_seal_review"},nodes={
 nano_fragment_review={id="nano_fragment_review",character="nanahoshi",day=3,background="laboratory",emotion="skeptical",
  text="La muestra de referencia que prestó Cliff responde al sello. Ese fragmento es de prueba: aún necesito otra lectura antes de que salgáis a las ruinas.",cards={
   listen={id="nano_d3_listen",rudy="Quiero oír primero la objeción que te hace desconfiar de tu propio resultado.",response="La temperatura cambió entre muestras. Me alegra que preguntes por el fallo posible; no suele ser la parte popular de mi trabajo.",expression="neutral",effects={score=2,love=0,trust=2,interest=2},next="nano_d3_control",variants={
    {id="nano_d3_listen_method",priority=10,requires={event="nano_method_noticed"},rudy="En la prueba de voz separaste dos cosas que parecían una sola. ¿Qué estamos confundiendo ahora?",response="Resonancia y reacción. Te acordabas del método, no solo del resultado. Acerca esa hoja; hay una comparación que quiero enseñarte.",expression="happy",effects={score=3,love=0,trust=3,interest=2}},
   }},
   encourage={id="nano_d3_encourage",rudy="Detectaste una variable que podía engañarnos. Ese descarte también es trabajo bien hecho.",response="Por fin un ánimo que no me exige encontrar una respuesta hoy. Bien; podemos repetirlo sin vendernos una certeza barata.",expression="happy",effects={score=2,love=0,trust=2,interest=2},next="nano_d3_control",variants={
    {id="nano_d3_encourage_precision",priority=10,requires={event="nano_precision_respected"},rudy="La otra vez contaste diez muestras. Hoy puedo ayudarte a descartar las que no cumplen el mismo criterio.",response="Y no has reducido diez a dos para salir antes. Eso sí me anima. Toma el registro; confiaré en tus marcas.",expression="happy",effects={score=3,love=0,trust=3,interest=2}},
   }},
   remember={id="nano_d3_remember",rudy="Anotaste que no debíamos tocar el fragmento después de activar una carta. He traído pinzas limpias.",response="Bien. Si contaminamos la muestra con tu propia voz encantada, perderemos la mañana distinguiendo el sello de nosotros.",expression="neutral",effects={score=2,love=0,trust=3,interest=0},next="nano_d3_control"},
   light_joke={id="nano_d3_joke",rudy="Tu hipótesis tiene suerte: la interrogarás con más rigor del que yo soporto antes del desayuno.",response="La hipótesis no protesta tanto. Aunque reconozco que tú traes mejores provisiones. Déjalas lejos de las muestras.",expression="happy",effects={score=1,love=0,trust=1,interest=2},next="nano_d3_control",variants={
    {id="nano_d3_joke_sarcasm",priority=10,requires={event="nano_shared_sarcasm"},rudy="¿Sigo primero en la lista de sospechosos o el fragmento ya me ha quitado el puesto?",response="Sigues primero. El fragmento todavía no ha intentado distraer a la investigadora con un chiste malo. Por poco.",expression="happy",effects={score=1,love=0,trust=2,interest=2}},
   }},
   self_joke={id="nano_d3_self_joke",rudy="Mi primera anotación dice brillante. Sospecho que no me contratarías como instrumento de medida.",response="No con esa escala. Escribe intensidad, duración y distancia; entonces hasta tus notas podrán aportar algo.",expression="happy",effects={score=1,love=0,trust=1,interest=0},next="nano_d3_record"},
   be_honest={id="nano_d3_honest",rudy="Quería que el destello confirmara mi esperanza. Tu duda me parece más fiable que mi entusiasmo.",response="No entregues tu criterio a otra persona, tampoco a mí. Pero admitir ese sesgo nos ahorra una mala decisión.",expression="neutral",effects={score=2,love=0,trust=3,interest=3},next="nano_d3_record",variants={
    {id="nano_d3_honest_trusted",priority=10,requires={affinity="nanahoshi",trust=40},rudy="Si mi urgencia está torciendo la lectura, prefiero que me lo digas. Confío en tu franqueza.",response="Lo está haciendo un poco. Y puedo decírtelo sin que cierres el cuaderno; eso facilita bastante trabajar contigo.",expression="happy",effects={score=3,love=0,trust=3,interest=3}},
   }},
   admit_error={id="nano_d3_admit",rudy="Moví la muestra antes de anotar la distancia. Esa lectura debe quedar fuera de la comparación.",response="Correcto. Márcala como inválida y conserva el dato: borrar el error haría más difícil descubrirlo después.",expression="neutral",effects={score=2,love=0,trust=3,interest=0},flags={"nano_sample_error_admitted"},next="nano_d3_record"},
   share_fear={id="nano_d3_fear",rudy="Me asusta que la cura dependa de un resultado que aún no podemos repetir.",response="A mí me preocupa prometerte uno que no existe. Hoy podemos conseguir una lectura reproducible; trabajemos con eso.",expression="worried",effects={score=1,love=0,trust=2,interest=0},next="nano_d3_control"},
   happy_reply={id="nano_d3_happy",rudy="La segunda lectura coincide con la primera. Al menos esta parte ya tiene dos apoyos.",response="Dos apoyos, no una demostración completa. Puedes alegrarte; solo deja espacio para la tercera medida.",expression="happy",effects={score=2,love=0,trust=1,interest=0},next="nano_d3_record"},
   bold_reply={id="nano_d3_bold",rudy="Probemos el fragmento a máxima intensidad y veremos dónde deja de responder.",response="¿Y cuando deje de responder el laboratorio? Primero fijaremos un límite seguro. La impaciencia no es un método.",expression="angry",effects={score=-1,love=0,trust=-3,interest=0},next="nano_d3_safety"},
   subtle_flirt={id="nano_d3_flirt",rudy="Es difícil impresionarte. Empiezo a entender por qué me interesa tanto conseguir una pregunta mejor.",response="Una pregunta mejor es un objetivo razonable. Si esperabas una sonrisa como nota final, no he publicado ese criterio.",expression="happy",effects={score=1,love=0,trust=1,interest=4},next="nano_d3_record",variants={
    {id="nano_d3_flirt_curious",priority=10,requires={affinity="nanahoshi",interest=4},rudy="Me quedé pensando en tu réplica del otro día. ¿Siempre desmontas un halago antes de aceptarlo?",response="Solo cuando viene sin pruebas. Este trae memoria, al menos. Puedes quedarte a discutirlo cuando cerremos el registro.",expression="happy",effects={score=1,love=0,trust=2,interest=4}},
   }},
   propose_plan={id="nano_d3_plan",rudy="Separamos tres muestras, fijamos la distancia y repetimos cada lectura antes de compararlas.",response="Añade una muestra sin sello. Si también brilla, habremos descubierto que el supuesto hallazgo venía de otra parte.",expression="neutral",effects={score=3,love=0,trust=2,interest=0},flags={"nano_control_agreed"},next="nano_d3_control"},
   analyze_runes={id="nano_d3_runes",rudy="La tercera marca está invertida. Compararé su copia con la del registro sin activar ninguna.",response="Sí. Si la inversión cambia la dirección del flujo, las ruinas pueden responder de otra manera aunque reconozcamos el dibujo.",expression="neutral",effects={score=3,love=0,trust=2,interest=0},flags={"nano_rune_compared"},next="nano_d3_record"},
   earth_barrier={id="nano_d3_barrier",rudy="Dejemos una protección entre la muestra y nosotros, sin acercarla al circuito de medida.",response="Aceptable si anotamos su posición. Una defensa cargada de maná también puede alterar el resultado; no la confundas con aire.",expression="neutral",effects={score=2,love=0,trust=2,interest=0},next="nano_d3_safety"},
  },fallback={id="nano_d3_pause",rudy="",response="Revisaré el cuaderno mientras piensas. Una casilla vacía es preferible a una respuesta inventada.",expression="neutral",effects={score=0,love=0,trust=0,interest=0},next="nano_d3_record"}},
 nano_d3_control={id="nano_d3_control",character="nanahoshi",expression="neutral",text="La muestra sin sello queda apartada. Si las ruinas contradicen esta lectura, conservad ambas: necesitaremos explicar la diferencia."},
 nano_d3_record={id="nano_d3_record",character="nanahoshi",expression="neutral",text="Anoto lo observado y dejo la conclusión abierta. Trae las marcas que encuentres; compararé las formas, no tus expectativas."},
 nano_d3_safety={id="nano_d3_safety",character="nanahoshi",expression="worried",text="No expondré a nadie para completar una tabla. Reducimos la intensidad y registramos también las condiciones de seguridad."},

 nano_seal_review={id="nano_seal_review",character="nanahoshi",day=4,background="laboratory",emotion="cautious",
  text="El registro de las ruinas confirma una dirección del sello. No confirma todavía cómo romperlo. Revisemos qué llevaréis a la botica.",cards={
   listen={id="nano_d4_listen",rudy="Antes de buscar una solución, quiero entender qué parte del sello sigue resistiendo tus explicaciones.",response="La respuesta depende de quién activa el artefacto. Has elegido justo la pregunta que no me deja cerrar el informe.",expression="neutral",effects={score=2,love=0,trust=2,interest=2},next="nano_d4_limits",variants={
    {id="nano_d4_listen_continuity",priority=10,requires={event="nano_rune_compared"},rudy="Ayer comparamos la marca invertida. ¿La dirección cambió también cuando cambió la persona que la activaba?",response="Exactamente. Esa relación está en el margen, todavía sin demostrar. Me gusta no tener que empezar la explicación desde cero.",expression="happy",effects={score=3,love=0,trust=3,interest=2}},
   }},
   encourage={id="nano_d4_encourage",rudy="Has reducido las opciones a dos. Podemos llevar preguntas concretas a la botica gracias a ese trabajo.",response="Dos opciones siguen siendo dos riesgos. Pero sí, es un avance. Puedes decirlo sin organizar una celebración en mi mesa.",expression="happy",effects={score=2,love=0,trust=2,interest=2},next="nano_d4_questions",variants={
    {id="nano_d4_encourage_control",priority=10,requires={event="nano_control_agreed"},rudy="La muestra de control que pediste nos evitó perseguir una falsa pista. Tu cautela nos ha dado tiempo.",response="Entonces úsalo bien y vuelve con el informe completo. Admito que resulta agradable que alguien recuerde para qué servía la cautela.",expression="happy",effects={score=3,love=0,trust=3,interest=2}},
   }},
   remember={id="nano_d4_remember",rudy="Traje las horas de cada activación, incluso las que no produjeron un destello.",response="Esas son las que suelen faltar. Las ausencias también dibujan un patrón; déjame ordenar el registro por intervalos.",expression="neutral",effects={score=2,love=0,trust=3,interest=0},next="nano_d4_record"},
   light_joke={id="nano_d4_joke",rudy="Tu informe tiene más advertencias que páginas. Eso explica por qué confío en que no intenta venderme nada.",response="Podría cobrar por advertencia. Con tu tendencia a saltártelas financiaríamos otro laboratorio, y quizá una silla decente.",expression="happy",effects={score=1,love=0,trust=1,interest=2},next="nano_d4_record",variants={
    {id="nano_d4_joke_familiar",priority=10,requires={affinity="nanahoshi",interest=6},rudy="He leído las notas al margen. Empiezo a sospechar que escondes ahí los mejores comentarios sobre mí.",response="No los escondo; uso letra pequeña para ahorrar papel. Pero puedes sentarte más cerca si de verdad has venido a leer.",expression="happy",effects={score=1,love=0,trust=2,interest=2}},
   }},
   change_subject={id="nano_d4_change",rudy="¿Podemos hablar de otra cosa antes de seguir con el sello? Necesito ordenar lo que escuché.",response="Cinco minutos. Apartaré el reactivo y luego volvemos a la pregunta pendiente. Cambiar de conversación no cambia la muestra.",expression="neutral",effects={score=0,love=0,trust=0,interest=0},next="nano_d4_limits"},
   self_joke={id="nano_d4_self_joke",rudy="Mi letra volvió irreconocible una hora. Por fortuna, mi talento para equivocarme deja muchas pistas.",response="La próxima vez escribe dos veces antes de cansarte. Esta podemos recuperarla comparando el orden de las otras entradas.",expression="happy",effects={score=1,love=0,trust=1,interest=0},next="nano_d4_record"},
   be_honest={id="nano_d4_honest",rudy="Buscaba una garantía y tú solo me ofreces lo que puedes probar. Respeto que sostengas ese límite.",response="Una garantía falsa sería más cómoda durante cinco minutos. Después tendrías que vivir con ella. Prefiero seguir siendo incómoda.",expression="neutral",effects={score=2,love=0,trust=3,interest=3},next="nano_d4_limits",variants={
    {id="nano_d4_honest_respected",priority=10,requires={all={{event="nano_honesty_respected"},{affinity="nanahoshi",trust=42}}},rudy="Cuando probamos la voz no prometiste curarme. Hoy tampoco necesito que finjas saberlo todo para confiar en tu ayuda.",response="Bien. Entonces puedo decirte que estoy preocupada por esta reacción sin que lo confundas con rendirme. Sigamos revisándola.",expression="worried",effects={score=3,love=0,trust=3,interest=3}},
   }},
   admit_error={id="nano_d4_admit",rudy="Me adelanté al llamar solución a una pista. Cambiaré esa palabra antes de llevar el informe.",response="Hazlo. Quien lo lea debe saber qué observamos y qué estamos suponiendo; una palabra exagerada puede decidir una dosis.",expression="neutral",effects={score=2,love=0,trust=3,interest=0},next="nano_d4_questions"},
   share_fear={id="nano_d4_fear",rudy="Me preocupa volver de la botica con otra esperanza provisional y decepcionar a mi familia.",response="Cuéntales qué sabemos antes de partir. No puedo resolver esa conversación, pero sí evitar que lleves información falsa a ella.",expression="worried",effects={score=1,love=0,trust=2,interest=0},next="nano_d4_limits"},
   happy_reply={id="nano_d4_happy",rudy="El registro ya permite descartar una mezcla. Me alegra llevar un riesgo menos a la botica.",response="Ese es un motivo sensato para alegrarse. Tacha la mezcla en ambas copias; el entusiasmo no debe dejar una receta vieja circulando.",expression="happy",effects={score=2,love=0,trust=1,interest=0},next="nano_d4_questions"},
   bold_reply={id="nano_d4_bold",rudy="Podría activar el sello sobre mí para resolver de una vez la duda que falta.",response="No eres material de laboratorio desechable. Si necesitas una respuesta inmediata, la respuesta es no. Busquemos una prueba limitada.",expression="angry",effects={score=-1,love=0,trust=-3,interest=0},next="nano_d4_limits"},
   angry_reply={id="nano_d4_angry",rudy="¡Otra lista de límites! Necesito que alguien termine esto, no que vuelva a señalar lo que ignora.",response="Y yo necesito que no conviertas tu miedo en órdenes. Puedo ayudarte a investigar; no aceptaré que me culpes por no inventar una cura.",expression="angry",animation="angry_shake",effects={score=-2,love=0,trust=-5,interest=-2},flags={"nano_boundaries_crossed"},next="nano_d4_boundaries"},
   sincere_apology={id="nano_d4_apology",rudy="Mi urgencia no te obliga a prometer resultados. Siento haber presionado cuando necesitábamos revisar.",response="Acepto la disculpa. El siguiente paso es respetar la prueba que hemos acordado, aunque tarde más de lo que quieras.",expression="neutral",effects={score=1,love=0,trust=2,interest=0},next="nano_d4_questions",variants={
    {id="nano_d4_apology_boundary",priority=20,requires={event="nano_boundaries_crossed"},rudy="Te culpé por no tener una cura. Fue injusto. No repetiré el experimento por mi cuenta para forzar tu respuesta.",response="Eso era lo que necesitaba oír. No recuperamos la confianza con una frase; empieza por dejar la muestra donde acordamos.",expression="worried",effects={score=1,love=0,trust=2,interest=0},flags={"nano_boundary_acknowledged"}},
   }},
   subtle_flirt={id="nano_d4_flirt",rudy="Tu forma de detectar una excusa antes de que la termine sigue siendo inquietantemente atractiva.",response="Una cualidad práctica para esta conversación. Si continúas, distinguiré el halago del intento de saltarte el protocolo.",expression="happy",effects={score=1,love=0,trust=1,interest=4},next="nano_d4_questions",variants={
    {id="nano_d4_flirt_familiar",priority=10,requires={affinity="nanahoshi",trust=42,interest=8},rudy="Cuando volvamos, me gustaría escuchar algo tuyo que no esté escrito en este informe. Si te apetece.",response="Puede ser. Pregunta cuando hayas vuelto y yo haya terminado. Y no escribas un sí en tus notas antes de tener la respuesta.",expression="happy",effects={score=1,love=0,trust=2,interest=4}},
   }},
   propose_plan={id="nano_d4_plan",rudy="Llevaremos dos copias, preguntaremos por cada componente y regresaremos antes de probar la mezcla.",response="Añade una muestra sellada para comparar la concentración. Ese plan sí me permite revisar lo que ocurra fuera del laboratorio.",expression="neutral",effects={score=3,love=0,trust=2,interest=0},next="nano_d4_questions"},
   analyze_runes={id="nano_d4_runes",rudy="Marcaré la dirección del flujo en la copia. Una receta correcta no servirá si aplicamos el sello al revés.",response="Y señala cuál de esas flechas es observación y cuál es hipótesis. No quiero que una suposición adquiera autoridad por estar bien dibujada.",expression="neutral",effects={score=3,love=0,trust=2,interest=0},next="nano_d4_record"},
   earth_barrier={id="nano_d4_barrier",rudy="Protegeremos la mesa antes de abrir la muestra y dejaremos una salida libre para todos.",response="De acuerdo. La barrera puede contener una descarga, pero no sustituye medir la dosis. Escribe ambas precauciones por separado.",expression="neutral",effects={score=2,love=0,trust=2,interest=0},next="nano_d4_questions"},
  },fallback={id="nano_d4_pause",rudy="",response="Relee las notas. No necesito una respuesta rápida; necesito que sepas qué estamos llevando a la botica.",expression="neutral",effects={score=0,love=0,trust=0,interest=0},next="nano_d4_record"}},
 nano_d4_limits={id="nano_d4_limits",character="nanahoshi",expression="worried",text="Seguimos sin una cura demostrada. Puedes contar con mi trabajo; las conclusiones tendrán que esperar a las pruebas."},
 nano_d4_record={id="nano_d4_record",character="nanahoshi",expression="neutral",text="El informe conserva los resultados que contradicen nuestra idea. Si alguien propone una mezcla, deberá explicarlos también."},
 nano_d4_questions={id="nano_d4_questions",character="nanahoshi",expression="neutral",text="He separado ingredientes, dosis y dudas pendientes. Llevad estas preguntas; traer una respuesta comprobable será suficiente por hoy."},
 nano_d4_boundaries={id="nano_d4_boundaries",character="nanahoshi",expression="angry",text="Pausa la prueba. Podemos retomar el trabajo cuando podamos discrepar sin convertir el desacuerdo en una exigencia."},
}}
